function normalizeZoomLinks(links) {
  return links.map((link) => ({ name: link.name.trim(), url: link.url.trim() })).filter((link) => link.name.length > 0 && link.url.length > 0);
}
function classroomHasZoomLinks(room) {
  return normalizeZoomLinks(cloneZoomLinks(room.zoomLinks)).length > 0;
}
function emptyZoomLinkDraft() {
  return { name: "", url: "" };
}

