// src/app/auth.interceptor.ts
var authInterceptor = (req, next) => {
  const auth = inject(AuthService);
  const token = auth.token();
  const headers = {};
  const tenantId = currentTenantId();
  if (tenantId) {
    headers["X-Tenant-Id"] = tenantId;
  }
  if (token) {
    headers["Authorization"] = `Bearer ${token}`;
  }
  return next(req.clone({ setHeaders: headers }));
};

// src/app/api-busy.interceptor.ts
var silentUrlParts = ["/media/watch-events", "/weekly-reports/top-students", "/photo"];
var apiBusyInterceptor = (req, next) => {
  if (silentUrlParts.some((part) => req.url.includes(part))) {
    return next(req);
  }
  const busy = inject(ApiBusyService);
  busy.begin();
  return next(req).pipe(finalize(() => busy.end()));
};

// src/app/app.config.ts
var appConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideZoneChangeDetection({ eventCoalescing: true }),
    provideAppInitializer(loadDefaultTenant),
    provideHttpClient(withInterceptors([authInterceptor, apiBusyInterceptor])),
    provideRouter(routes, withInMemoryScrolling({ anchorScrolling: "enabled" })),
    // Production builds only; registering once the app is idle keeps it off the first page load.
    // app-sw.js is Angular's worker plus the app icon's unread badge for pushes that arrive while closed.
    provideServiceWorker("app-sw.js", {
      enabled: !isDevMode(),
      registrationStrategy: "registerWhenStable:30000"
    })
  ]
};

